'use strict';
let data=[],index=0,lang='python',problemIndex=0;const drafts={};const key=()=>data[0]?.id+'python:0';function saveDraft(){const editor=document.getElementById('editor');if(editor&&data.length){if(drafts[key()]!==editor.value)window.academyMarkDirty?.();drafts[key()]=editor.value;}}function switchTab(){saveDraft();document.querySelectorAll('.reader-pane').forEach(p=>p.hidden=p.id!=='pane-lab');document.querySelectorAll('[data-reader-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.readerTab==='lab');b.setAttribute('aria-selected',String(b.dataset.readerTab==='lab'));});document.getElementById('editor')?.scrollIntoView({block:'center',behavior:'smooth'});}window.codeTrailMockActive=()=>false;window.academyTutorContext=(l,code)=>{data=[{id:l.id,title:l.title,lesson:l.sections.map(s=>s.heading+'\n'+s.body).join('\n'),problem:{prompt:l.task.brief,input:'See the worked example and task specification',output:l.example.expectedOutput||'Explain the expected result before running.'}}];drafts[key()]=code;};
